import { code } from '../../code.ts';
import { androidClass, androidNamespace, displayName } from '../names.ts';
import type { AndroidValues } from '../values.ts';

// The path of the file in plugins/android.
export const path = ({ plugin: { id } }: AndroidValues) =>
  `${id}/src/main/java/${androidNamespace(id).replaceAll('.', '/')}/${androidClass(id)}.kt`;

export default ({ plugin: { id, backends } }: AndroidValues) => code`
// Generated by plugins/tools/generate.ts from plugins/plugins/${id}/plugin.json; do not edit.
package ${androidNamespace(id)}

import org.maplibre.android.RenderingEngine

/** The ${displayName(id)} plugin. */
object ${androidClass(id)} {
    init {
        // The plugin retains native callbacks for the process lifetime; never unload it.
        System.loadLibrary("${id}")
    }

    /**
     * Registers the plugin's layer types. Call it after \`MapLibre.getInstance()\` and before loading a style that uses
     * them. Registering again succeeds.
     *
     * @return \`false\` without registering when the active renderer is not one of the plugin's backends (${backends.join(', ')}).
     * @throws IllegalStateException when MapLibre rejects the plugin.
     */
    @JvmStatic
    fun register(): Boolean {
        val engine = RenderingEngine.getCurrentType()
        val supported = when (engine) {
            RenderingEngine.Type.OPENGL -> ${backends.includes('opengl')}
            RenderingEngine.Type.VULKAN -> ${backends.includes('vulkan')}
            else -> false
        }
        if (!supported) return false
        val library = if (BuildConfig.MULTI_BACKEND && engine == RenderingEngine.Type.OPENGL) {
            "libmaplibre-opengl.so"
        } else {
            "libmaplibre.so"
        }
        registerNative(library)
        return true
    }

    @JvmStatic
    private external fun registerNative(libraryName: String)
}
`;
